import{_ as s,C as a,o as l,c as r,j as t,a as o,E as i,a2 as d}from"./chunks/framework.C0pL2NcE.js";const v=JSON.parse('{"title":"5. Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/changelog.md","filePath":"gdd/changelog.md"}'),h={name:"gdd/changelog.md"},g={id:"latest-main",tabindex:"-1"};function c(u,e,w,p,m,f){const n=a("Badge");return l(),r("div",null,[e[3]||(e[3]=t("h1",{id:"_5-changelog",tabindex:"-1"},[o("5. Changelog "),t("a",{class:"header-anchor",href:"#_5-changelog","aria-label":'Permalink to "5. Changelog"'},"​")],-1)),e[4]||(e[4]=t("p",null,[o("Every published version stays playable at its own URL. The "),t("a",{href:"https://tuandds.github.io/colony-flow-sand/",target:"_blank",rel:"noreferrer"},"landing page"),o(" lists them all.")],-1)),t("h2",g,[e[0]||(e[0]=o("latest (main) ",-1)),i(n,{type:"tip",text:"Live"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#latest-main","aria-label":'Permalink to "latest (main) <Badge type="tip" text="Live" />"'},"​",-1))]),e[5]||(e[5]=d('<ul><li><strong>Same sand scale in every level:</strong> the frame is always 22 cells tall, so sand cells and grains are the same size in every level; smaller pictures (Cherries, Ice Cream and others) now sit centred in the frame instead of being blown up. In the Level Editor, picture size (12–22) sets how big the picture is in the frame. Recorded editor wins need to be made again; the bot still clears the same levels as before.</li></ul><p><a href="https://tuandds.github.io/colony-flow-sand/demo/" target="_blank" rel="noreferrer">Play latest</a></p><h2 id="v1-0-1" tabindex="-1">v1.0.1 <a class="header-anchor" href="#v1-0-1" aria-label="Permalink to &quot;v1.0.1&quot;">​</a></h2><ul><li><strong>Edited levels:</strong> nine built-in levels were changed in the Level Editor (pictures; Cherries, Rocket and Penguin also got nests set by hand). Garden Snail, Rocket and Penguin have no recorded win yet, and the test bot gets stuck on them. The eyes of Goldfish, Little Owl, Garden Snail and Penguin use the outline colour (Little Owl: nest seed 5).</li><li><strong>Levels:</strong> 10 new original pictures (Cherries, Ice Cream, Goldfish, Cupcake, Little Owl, Hot Air Balloon, Cactus Pot, Garden Snail, Rocket, Penguin) with a dark outline and rising difficulty. Each one was cleared by a test bot when it was added; the old large levels 4 and 5 are gone.</li><li><strong>Level Editor</strong> (<code>/demo/editor.html</code>), laid out like the team&#39;s level editor template, with Editor and Organizer modes. Import an image to get a sand picture made grain by grain in the editor&#39;s sand colours, closest by eye (CIELAB), keeping small distinct details. Paint with brush, fill and replace tools. Nests are generated from a recorded winning play and checked by replaying it; you can also edit them by hand. The Level Bank has search, filters, version history and backups; the Organizer handles chapter sets, play, Auto Play and checks for a whole set, and CSV/JSON export. Levels are saved in the browser and played with <code>?custom=1</code>. See the <a href="/colony-flow-sand/docs/guide/level-editor">guide</a>.</li><li><strong>Editor pictures fill the frame:</strong> custom pictures cover the frame&#39;s whole inside (wider than the built-in square pictures), and the Sand Editor shows exactly that area, so a picture that touches the edge in the editor touches the frame in the game. The generator can fit the image or fill the frame.</li><li><strong>Win screen like Colony Flow:</strong> &quot;Victory!&quot; pops in letter by letter over glow and turning rays, and a big green Next button pulses (Colony Flow&#39;s win art, animated with tweens).</li><li><strong>Colour Bank like the template:</strong> an Active Palette per level (tap or drag colours in, keys 1–0, eraser), a Bank you can reorder, add to and edit (name, colour, delete) with long-press, and an option to build a picture from the Active Palette only.</li><li><strong>Colour Bank colours:</strong> the Bank adds the template&#39;s colours the game lacked, purples included, and drops colours that looked alike (24 colours); a Bank saved earlier is updated once, keeping your own colours.</li><li><strong>Funnel order:</strong> sand in the funnel now goes down the hole oldest first. Before, the hole always took the bottom row from the left, so newer sand falling into those cells jumped ahead while older sand lying further along waited (up to 8 s). Recorded wins in the Level Editor were made under the old rules: run Auto-generate nests again for those levels. The built-in levels still win with the test bot.</li><li><strong>Game levels in the Level Editor:</strong> the 10 built-in levels are in the Level Bank (chapter set &quot;Game&quot;), looking and playing exactly as in the game. When you save a change to one, the game plays the changed version: at once in the same browser, and on the dev server the editor also writes it to <code>src/game/level-edits.json</code> so it can be committed and published.</li><li><strong>Nest Editor drag and drop:</strong> drag a nest onto another to swap them, or onto a column&#39;s ＋ to move it there.</li><li><strong>Nest columns per level:</strong> a level can have 2 to 6 nest columns (default 4, as in every built-in level); the Nest Editor has a picker for it.</li><li><strong>Rules:</strong> the sand, funnel and particle randomness now comes from a generator seeded per level, and ants walk from a nest&#39;s front slot rather than its sliding position, so the same swipes always play out the same. The built-in levels were re-checked with the test bot; Rocket now uses seed 1.</li><li><strong>Funnel:</strong> the funnel is as wide as the sand frame, so sand falls straight into it from anywhere along the board; sand on its gentle walls slides toward the hole. Little Owl now uses nest seed 6.</li><li><strong>Conveyor capacity:</strong> the conveyor holds 30 blocks (was 24). The test bot still clears every level.</li><li><strong>Screen layout:</strong> the sand board is taller (inside 824 × 744 px, same width), so built-in pictures are bigger; the conveyor is slimmer with smaller blocks (32 px), and the nests sit lower so the third row shows about two thirds above the tray. Penguin got a new nest seed (6) so the test bot still clears every level. Level editor pictures made for the old frame are re-centred and need their nests generated again.</li><li><strong>Losing:</strong> the level is lost only when the conveyor is full and no block on it can go into a nest any more; before, a full belt with one more block waiting in the hole lost even while ants could still take blocks. The end panel now says &quot;No block on the belt fits a nest&quot;.</li><li><strong>Block sound:</strong> a new block landing on the belt now plays a short, soft cube sound (<code>cube_break_1</code>) instead of the long, loud box drop, which piled up into a shrill noise.</li><li><strong>Conveyor bar:</strong> the bar in the middle of the conveyor now fills with how full the belt is (green, yellow from 60 %, red from 85 %); before, the fill was drawn under the white bar and only the % showed.</li><li><strong>Nest numbers:</strong> nests waiting behind the front row show their number without the dark stroke: white on darker tiles, a darker shade of the nest colour on light ones.</li><li><strong>Nests:</strong> the nests now use Colony Flow&#39;s lidded nest box (<code>Box_v2_T</code> + <code>Box_v2_B</code>), with the white outline hugging its shape.</li></ul><p><a href="https://tuandds.github.io/colony-flow-sand/v1.0.1/demo/" target="_blank" rel="noreferrer">Play v1.0.1</a> · <a href="https://tuandds.github.io/colony-flow-sand/v1.0.1/docs/" target="_blank" rel="noreferrer">Docs v1.0.1</a></p><h2 id="v1-0-0" tabindex="-1">v1.0.0 <a class="header-anchor" href="#v1-0-0" aria-label="Permalink to &quot;v1.0.0&quot;">​</a></h2><ul><li><strong>Sand:</strong> swipe the picture to set sand free; loose sand falls, slides off slopes and past the picture edges, and leaves through the bottom of the board. Every colour fits whole blocks exactly, so no sand is left over.</li><li><strong>Funnel and hole:</strong> sand piles up in the funnel and trickles into the hole; a finished block waiting in the hole plugs it until it drops onto the conveyor.</li><li><strong>Conveyor:</strong> 24 slots; the bar in the middle shows how full it is, and overflowing it loses the level.</li><li><strong>Nests and ants:</strong> Colony Flow&#39;s 3D nests, ants and blocks; ants carry matching blocks home, full nests pop and the column slides up. Front-row nests have a white outline, queued nests are lower and paler.</li><li><strong>Levels:</strong> 10 levels; levels 1–5 use Colony Flow pictures. Levels 4 and 5 are very large and not yet winnable in practice (see <a href="./roadmap#known-issues">Known issues</a>).</li><li><strong>UI:</strong> settings with Resume, Restart and a cheat to jump to any level; x2 speed; boosters are shown but do nothing yet.</li><li><strong>Start-up:</strong> the game no longer waits forever if the web font is slow, shows an error instead of hanging, and shows the nests on the start screen.</li><li><strong>Game Design Document:</strong> overview, core loop, rules with the numbers from the code, roadmap and known issues.</li></ul><p><a href="https://tuandds.github.io/colony-flow-sand/v1.0.0/demo/" target="_blank" rel="noreferrer">Play v1.0.0</a> · <a href="https://tuandds.github.io/colony-flow-sand/v1.0.0/docs/" target="_blank" rel="noreferrer">Docs v1.0.0</a></p><h2 id="document-history" tabindex="-1">Document history <a class="header-anchor" href="#document-history" aria-label="Permalink to &quot;Document history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>2026-10-27</td><td>GDD created</td></tr><tr><td>2026-10-27</td><td>Released v1.0.0</td></tr><tr><td>2026-10-28</td><td>Released v1.0.1</td></tr></tbody></table>',10))])}const y=s(h,[["render",c]]);export{v as __pageData,y as default};
